/* Loud Lion 80 by KhelVers — https://uiverse.io/KhelVers/loud-lion-80 */
.btnContainer {

  background: #e0e0e0;
  -webkit-box-shadow: 6px 6px 16px #bebebe,
             -6px -6px 16px #ffffff9a;
  box-shadow: 6px 6px 16px #bebebe,
             -6px -6px 16px #ffffff9a;

  width: 160px;
  height: 60px;

  border: none;
  border-radius: 16px;

  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-pack: center;
  -ms-flex-pack: center;
  justify-content: center;
  -webkit-box-align: center;
  -ms-flex-align: center;
  align-items: center;
}

.button {

  background: #e0e0e0;

  font-size: 20px;
  font-weight: 600;

  height: 85%;
  width: 95%;

  border: none;
  border-radius: 14px;

  -webkit-transition: all 250ms ease-in-out;
  transition: all 250ms ease-in-out;
}

.button:hover {

  background: #e0e0e0;
  -webkit-box-shadow: inset 5px 5px 4px #c0c0c0,
              inset -5px -5px 4px #dddddd;
  box-shadow: inset 5px 5px 4px #c0c0c0,
              inset -5px -5px 4px #dddddd;

  font-size: 20px;
  font-weight: 400;
  color: #333333;
}
